from __future__ import annotations

import os
from dataclasses import dataclass, field
from typing import Dict, List

from . import fsops
from .planner import CREATE, DELETE, KEEP, UPDATE, PlanEntry, build_plan


@dataclass
class SyncResult:
    \"\"\"一次镜像同步的结果。

    \`\`created\`\` / \`\`updated\`\` / \`\`deleted\`\` / \`\`kept\`\` 记录已完成的相对
    路径；\`\`failed\`\` 记录没有完成的条目，每一项形如::

        {\"action\": \"delete\", \"relpath\": \"logs/app.old\", \"error\": \"...\"}
    \"\"\"

    created: List[str] = field(default_factory=list)
    updated: List[str] = field(default_factory=list)
    deleted: List[str] = field(default_factory=list)
    kept: List[str] = field(default_factory=list)
    failed: List[Dict[str, str]] = field(default_factory=list)

    @property
    def ok(self) -> bool:
        \"\"\"没有任何条目失败时为 \`\`True\`\`。\"\"\"
        return not self.failed


def _clear_target_path(target_path: str) -> None:
    \"\"\"清除目标路径上的所有内容（文件或目录树）。

    如果目标路径上有只读文件或目录，会先清除只读属性。
    \"\"\"
    if not os.path.exists(target_path):
        return

    if os.path.isfile(target_path):
        fsops.remove_file(target_path)
    elif os.path.isdir(target_path):
        fsops.remove_tree(target_path)


def _ensure_parent_is_directory(target_path: str) -> None:
    \"\"\"确保目标路径的父目录存在且是目录。

    如果父目录路径上存在同名文件，会先删除该文件。
    \"\"\"
    parent = os.path.dirname(target_path)
    if not parent:
        return

    if os.path.exists(parent):
        if os.path.isfile(parent):
            # 父路径是文件，需要删除
            fsops.remove_file(parent)
            os.makedirs(parent, exist_ok=True)
        elif not os.path.isdir(parent):
            # 父路径存在但不是目录也不是文件（可能是符号链接等），删除并重建
            _clear_target_path(parent)
            os.makedirs(parent, exist_ok=True)
    else:
        # 递归确保所有祖先目录都存在
        _ensure_parent_is_directory(parent)
        os.makedirs(parent, exist_ok=True)


def _apply(entry: PlanEntry) -> None:
    \"\"\"应用一条同步动作。\"\"\"
    if entry.action in (CREATE, UPDATE):
        # 确保父目录存在且是目录
        _ensure_parent_is_directory(entry.target)

        # 如果目标路径已存在，检查是否需要清除
        if os.path.exists(entry.target):
            # 如果目标是目录而源是文件，需要先删除目录
            if os.path.isdir(entry.target):
                _clear_target_path(entry.target)

        # 复制文件
